#!/usr/bin/env node
// 把 scripts/vendor/tiny-pinyin/dist 的 CommonJS 模块打成浏览器可用的全局脚本。
//
// 为什么要有这一步：dist/ 是给 Node 用的（module.exports + require），浏览器里既没有
// module 也没有 require。以前预研目录里有一份打包脚本，v3.25 前清出仓库了，这里重写。
// 产物 assets/vendor/pinyin.min.js 只在 pinyin-convert 工具页按需注入，不进首屏。
//
// 用法：
//   node scripts/build-pinyin-bundle.mjs           # 生成 assets/vendor/pinyin.min.js
//   node scripts/build-pinyin-bundle.mjs --check  # 只检查产物是否最新（CI 用）
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { gzipSync } from 'node:zlib';
import { isMainModule } from './lib/is-main.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const DIST = join(root, 'scripts', 'vendor', 'tiny-pinyin', 'dist');
const OUT = join(root, 'assets', 'vendor', 'pinyin.min.js');

// 只打运行时真正会走到的四个模块：index（环境探测 + 补丁）→ core（解析）→ dict（字表），
// 以及 index 引入的 ICU 56l 补丁。ie / safari 两个补丁是给老版本浏览器/Node 的，
// 现代浏览器用不到，不值得让每个访客多下一次。
const FILES = ['index.js', 'core.js', 'dict.js', 'patchers/56l.js'];

/** 把 dist 下的 CommonJS 源码拼成一个 IIFE，内部自带一个极小的 require 实现 */
export function buildPinyinBundle() {
  const parts = [];
  for (const f of FILES) {
    const p = join(DIST, f);
    if (!existsSync(p)) throw new Error(`缺数据源 ${p}：请先确认 scripts/vendor/tiny-pinyin/dist 完整`);
    const src = readFileSync(p, 'utf8').replace(/\r\n/g, '\n');
    // 源码里所有 require() 都必须能在 FILES 里解析，否则产物会在浏览器里静默 undefined。
    for (const m of src.matchAll(/require\(\s*['"]([^'"]+)['"]\s*\)/g)) {
      const key = m[1].replace(/^\.\//, '').replace(/\.js$/, '') + '.js';
      if (!FILES.includes(key)) throw new Error(`${f} 引用了未打包的模块 ${m[1]}（把 ${key} 加进 FILES）`);
    }
    parts.push(`  ${JSON.stringify(f)}: function (module, exports, require) {\n${src}\n  }`);
  }

  const head = `/*! TinyPinyin 1.3.2 | MIT | https://github.com/creeperyang/pinyin
 * Generated by scripts/build-pinyin-bundle.mjs from scripts/vendor/tiny-pinyin/dist.
 * Exposes window.TinyPinyin (convertToPinyin / parse / isSupported).
 * The dictionary gives syllables only (no tone marks) and uses the common reading
 * for polyphonic characters; the tool page states this explicitly.
 * Loaded on demand by tools/pinyin-convert/run.js. NOT part of the first screen.
 */
`;
  return (
    head +
    '(function () {\n' +
    '  var __src = {\n' +
    parts.join(',\n') +
    '\n  };\n' +
    '  var __cache = {};\n' +
    '  function __req(id) {\n' +
    '    var key = String(id).replace(/^\\.\\//, "");\n' +
    '    if (!/\\.js$/.test(key)) key += ".js";\n' +
    '    if (__cache[key]) return __cache[key].exports;\n' +
    '    var m = (__cache[key] = { exports: {} });\n' +
    '    if (!__src[key]) throw new Error("TinyPinyin module not bundled: " + id);\n' +
    '    __src[key](m, m.exports, __req);\n' +
    '    return m.exports;\n' +
    '  }\n' +
    '  window.TinyPinyin = __req("./index.js");\n' +
    '})();\n'
  );
}

if (isMainModule(import.meta.url)) {
  const text = buildPinyinBundle();
  const old = existsSync(OUT) ? readFileSync(OUT, 'utf8').replace(/\r\n/g, '\n') : '';
  if (process.argv.includes('--check')) {
    if (old !== text) {
      console.error('❌ assets/vendor/pinyin.min.js 不是最新，请运行 node scripts/build-pinyin-bundle.mjs');
      process.exit(1);
    }
    console.log('✅ pinyin.min.js 与数据源一致');
  } else if (old === text) {
    console.log('✅ pinyin.min.js 已是最新');
  } else {
    writeFileSync(OUT, text, 'utf8');
    const b = Buffer.from(text, 'utf8');
    console.log(
      `✅ 已生成 assets/vendor/pinyin.min.js（raw ${b.length} B / gzip ${gzipSync(b, { level: 9 }).length} B）`
    );
  }
}
